const path = "deepwiki_mcp.user.personaldeepwikimcp.ask_question";
const questions = [
  {
    repoName: "openai/codex",
    question: "For the current Sign in with ChatGPT subscription authentication used by Codex CLI, identify the exact local authorization-code PKCE flow: client identifier ownership/category, authorize and token endpoints, loopback redirect URI/port behavior, state/PKCE validation, scopes and special authorize parameters, token response fields, refresh-token rotation behavior, account-id derivation, credential persistence, and refresh concurrency. Distinguish what an external personal local client can interoperate with from what requires a separately registered hosted redirect. Cite source files/functions and call out security constraints."
  },
  {
    repoName: "numman-ali/opencode-openai-codex-auth",
    question: "Explain the repository's complete ChatGPT Plus/Pro OAuth lifecycle for personal use: local callback and manual fallback, PKCE/state, fixed client/redirect/endpoints/scopes/special parameters, code exchange, token profile fields, account-id extraction, automatic refresh and rotating refresh persistence, request headers/backend path, failure/re-auth behavior, logging risks, and production-use warning. Cite files/functions. Identify patterns Bundjil can independently implement with Effect and patterns it should explicitly reject."
  }
];
const results = await Promise.all(questions.map((input) => tools[path](input)));
return results.map((result, index) => result.ok
  ? { index, result: result.data.structuredContent?.result ?? result.data.content }
  : { index, error: result.error });

