    11	/**
    12	 * Start a small local HTTP server that waits for /auth/callback and returns the code
    13	 * @param options - OAuth state for validation
    14	 * @returns Promise that resolves to server info
    15	 */
    16	export function startLocalOAuthServer({ state }: { state: string }): Promise<OAuthServerInfo> {
    17		const server = http.createServer((req, res) => {
    18			try {
    19				const url = new URL(req.url || "", "http://localhost");
    20				if (url.pathname !== "/auth/callback") {
    21					res.statusCode = 404;
    22					res.end("Not found");
    23					return;
    24				}
    25				if (url.searchParams.get("state") !== state) {
    26					res.statusCode = 400;
    27					res.end("State mismatch");
    28					return;
    29				}
    30				const code = url.searchParams.get("code");
    31				if (!code) {
    32					res.statusCode = 400;
    33					res.end("Missing authorization code");
    34					return;
    35				}
    36				res.statusCode = 200;
    37				res.setHeader("Content-Type", "text/html; charset=utf-8");
    38				res.end(successHtml);
    39				(server as http.Server & { _lastCode?: string })._lastCode = code;
    40			} catch {
    41				res.statusCode = 500;
    42				res.end("Internal error");
    43			}
    44		});
    45	
    46		return new Promise((resolve) => {
    47			server
    48				.listen(1455, "127.0.0.1", () => {
    49					resolve({
    50						port: 1455,
    51						ready: true,
    52						close: () => server.close(),
    53						waitForCode: async () => {
    54							const poll = () => new Promise<void>((r) => setTimeout(r, 100));
    55							for (let i = 0; i < 600; i++) {
    56								const lastCode = (server as http.Server & { _lastCode?: string })._lastCode;
    57								if (lastCode) return { code: lastCode };
